<script setup>
import {ref,onMounted} from 'vue'
import {Mail,Send,Clock,RefreshCw,CheckCircle2} from 'lucide-vue-next'
import {request} from './client'
import {previewMode} from '../preview/mode'
const props=defineProps({member:Object,hideHistory:Boolean}),emit=defineEmits(['changed'])
const email=ref(''),rows=ref([]),message=ref(''),error=ref(''),busy=ref(false)
async function load(){if(props.hideHistory)return;rows.value=await request('invitations','list_invitations')}
async function send(){busy.value=true;error.value='';try{const r=await request('invitations',props.member.role==='Admin'?'invite_teacher':'request_by_email',{email:email.value});message.value=previewMode?'Saved in this preview only. No email was sent.':r.message||'Invitation email queued. The teacher signs in with that email to respond.';email.value='';await load();emit('changed')}catch(e){error.value=e.message}finally{busy.value=false}}
async function respond(r,decision){busy.value=true;error.value='';try{await request('invitations','respond',{name:r.name,decision});message.value=decision==='Accepted'?'Institute connected. Use your workspace dropdown to switch.':'Invitation declined.';await load();window.dispatchEvent(new Event('sisu-memberships'));emit('changed')}catch(e){error.value=e.message}finally{busy.value=false}}
function date(value){return value?new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(String(value).replace(' ','T')+'+05:30')):'—'}
onMounted(()=>load().catch(e=>error.value=e.message))
</script>
<template>
<div class="membership-mail-group">
<section class="membership-mail">
 <header class="membership-mail-heading"><div class="membership-mail-icon"><Mail :size="24"/></div><div><h2>{{member.role==='Admin'?'Invite a teacher':'Connect with an institute'}}</h2><p>{{member.role==='Admin'?'Build your teaching team. Send an invitation to their SISU login email.':'Request to join an institute using its owner’s email.'}}</p></div></header>
 <form class="membership-mail-form" @submit.prevent="send"><label>{{member.role==='Admin'?'Teacher email address':'Institute owner email'}}<input v-model="email" type="email" autocomplete="email" required maxlength="254" placeholder="name@example.com" :disabled="busy"></label><button class="button primary" :disabled="busy"><Send :size="16"/>{{busy?'Please wait…':member.role==='Admin'?'Send invitation':'Request to join'}}</button></form>
 <p class="membership-mail-hint"><Clock :size="15"/>Invitations expire after 7 days. Teachers can accept from their email link or SISU Invitations.</p>
 <p v-if="message" class="membership-mail-success" role="status">{{message}}</p><p v-if="error" role="alert" class="error">{{error}}</p>
</section>
<section v-if="!hideHistory" class="membership-mail invitation-history" aria-label="Invitation history">
 <div class="membership-mail-list-heading"><h3>{{member.role==='Admin'?'Sent invitations':'Your invitations'}} <span>{{rows.length}}</span></h3><button class="membership-mail-refresh" :disabled="busy" @click="load().catch(e=>error=e.message)"><RefreshCw :size="15"/>Refresh</button></div>
 <p v-if="!rows.length" class="membership-mail-empty">No invitations yet. Invitations and responses will appear here.</p>
 <div v-if="rows.length" class="invitation-card-grid">
 <article v-for="r in rows" :key="r.name" class="invitation-card">
  <header class="invitation-card-header"><div class="invitation-recipient"><Mail :size="18"/><strong>{{member.role==='Admin'?r.invite_email:r.institute_title}}</strong></div><span class="invitation-state" :class="{connected:r.connected,pending:r.status==='Pending'&&!r.expired}"><CheckCircle2 v-if="r.connected" :size="13"/>{{r.expired?'Expired':r.connected?'Connected':r.status==='Declined'?'Rejected':r.status}}</span></header>
  <dl class="invitation-card-dates"><div><dt>Invitation sent</dt><dd>{{date(r.creation)}}</dd></div><div><dt>{{r.responded_at?(r.connected?'Connected on':'Responded on'):'Respond by'}}</dt><dd>{{date(r.responded_at||r.expires_at)}}</dd></div></dl>
  <footer v-if="r.email_status" class="invitation-card-delivery"><Send :size="14"/><span>{{r.email_status}}</span></footer>
  <div v-if="member.role==='Teacher'&&!r.expired&&r.status==='Pending'" class="invitation-card-actions"><button class="button primary small" :disabled="busy" @click="respond(r,'Accepted')">Accept invitation</button><button class="button subtle small" :disabled="busy" @click="respond(r,'Declined')">Reject</button></div>
 </article>
 </div>
 <p class="membership-mail-foot">When a teacher accepts, their institute workspace connects automatically. Assign their classes from your teaching team.</p>
</section>
</div>
</template>
<style>
.membership-mail{padding:28px;margin:24px 0 34px;border:1px solid #e4dbee;border-radius:16px;background:#fff}.membership-mail-heading{display:flex;gap:16px;align-items:center}.membership-mail-icon{display:grid;place-items:center;flex:none;width:48px;height:48px;border-radius:12px;background:#f2ebf9;color:#592c91}.membership-mail h2{font-size:21px;margin:0}.membership-mail p{font-size:13px;line-height:1.8;margin:8px 0;color:#71617e}.membership-mail-form{display:flex;align-items:end;gap:14px;margin:24px 0 12px;max-width:880px}.membership-mail-form label{display:grid;gap:9px;font-size:13px;flex:1;min-width:0}.membership-mail input{width:100%;height:48px;border:1px solid #cbbadd;border-radius:10px;padding:12px 15px;background:#fff;color:#34233f;box-sizing:border-box}.membership-mail input::placeholder{color:#776a84}.membership-mail input:focus{outline:2px solid #9d79c5;outline-offset:2px}.membership-mail .button{min-height:48px;display:inline-flex;gap:9px;align-items:center;justify-content:center}.membership-mail .button.primary{background:#592c91!important;color:#fff!important}.membership-mail .membership-mail-hint{display:flex;gap:8px;align-items:center;font-size:12px}.membership-mail-list-heading{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #e7deef;margin-top:26px;padding-top:20px}.membership-mail-list-heading h3{font-size:15px;margin:0}.membership-mail-list-heading h3 span{background:#f3ecfa;border-radius:6px;padding:3px 7px;margin-left:5px;font-size:11px;color:#674482}.membership-mail-refresh{display:flex;align-items:center;gap:7px;border:0;background:transparent;color:#592c91;min-height:40px;padding:8px;cursor:pointer}.membership-mail small{display:block;font-size:11px;line-height:1.9;color:#776a84}.invitation-row{display:flex;gap:20px;align-items:center;padding:20px 0;border-bottom:1px solid #eee8f3}.invitation-recipient{flex:1;min-width:0}.invitation-row strong{display:block;font-size:14px;overflow-wrap:anywhere;margin-bottom:5px}.invitation-delivery{text-align:right}.invitation-state{display:inline-flex;align-items:center;gap:6px;padding:5px 9px;background:#f1eef4;border-radius:7px;font-size:11px;margin-bottom:6px;color:#695d76}.invitation-state.pending{background:#fff3d9;color:#805921}.invitation-state.connected{background:#e7f4ed;color:#236948}.membership-mail .membership-mail-success{padding:12px 16px;border-radius:9px;background:#eaf6ef;color:#276c49}.membership-mail .membership-mail-foot{font-size:12px;margin:18px 0 0}.membership-mail .membership-mail-empty{padding:20px 0}.membership-mail button:focus-visible{outline:3px solid #a985cf;outline-offset:3px}@media(max-width:650px){.membership-mail{padding:20px}.membership-mail-form{display:grid}.invitation-row{flex-wrap:wrap;gap:10px}.invitation-delivery{text-align:left}.membership-mail-heading{align-items:flex-start}.membership-mail .membership-mail-hint{align-items:flex-start}}

.membership-mail-group{margin:24px 0 34px}.membership-mail-group>.membership-mail{margin:0 0 20px}.membership-mail-group>.invitation-history{padding:0;border:0;background:transparent}.invitation-history .membership-mail-list-heading{border:0;padding:0;margin:24px 0 12px}.invitation-history .membership-mail-list-heading h3{font-size:18px}.invitation-card-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,400px),1fr));gap:16px}.invitation-card{padding:22px;border:1px solid #e4dbee;border-radius:14px;background:#fff;max-width:740px}.invitation-card-header{display:flex;gap:16px;align-items:flex-start;justify-content:space-between}.invitation-card .invitation-recipient{display:flex;align-items:flex-start;gap:10px;min-width:0}.invitation-card .invitation-recipient svg{flex:none;color:#795597;margin-top:2px}.invitation-card strong{font-size:14px;line-height:1.6;overflow-wrap:anywhere}.invitation-card .invitation-state{flex:none;margin:0}.invitation-card-dates{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:22px 0}.invitation-card-dates dt{font-size:12px;color:#786b83;margin-bottom:7px}.invitation-card-dates dd{font-size:13px;font-weight:600;color:#42324f;margin:0;line-height:1.6}.invitation-card-delivery{display:flex;gap:8px;align-items:center;border-top:1px solid #eee7f4;padding-top:14px;font-size:12px;color:#776684}.invitation-card-actions{display:flex;gap:10px;margin-top:16px}.invitation-history .membership-mail-foot{max-width:740px;margin-top:14px}@media(max-width:520px){.invitation-card{padding:18px}.invitation-card-header{flex-wrap:wrap;gap:12px}.invitation-card-dates{grid-template-columns:1fr;gap:14px}.invitation-card-actions{flex-wrap:wrap}}
</style>
